SELECT wr.id, wr.code, wr.purchase_order_id, wr.purchase_order_code, wr.supplier_name, wr.approve_status, wr.invalid_status, wrd.sku_id, wrd.sku_no, wr.bill_date, wrd.receive_qty, wr.delivery_warehouse_name, wr.receive_user_name, wr.purchase_user_name, wrd.purchase_qty, wrd.exceed_qty, wr.approve_user_name, wr.create_user_name, wrd.purchase_order_detail_id, wrd.remark, wr.create_time FROM po_receive_detail wrd INNER JOIN po_receive wr ON wrd.main_id = wr.id AND wrd.is_deleted = FALSE WHERE wr.is_deleted = FALSE
and wr.code = #{params.code}
and wrd.sku_no in
#{item}
and wr.supplier_id in
#{item}
and wr.purchase_order_code = #{params.purchaseOrderCode}
and wr.invalid_status = #{params.invalidStatus}
and wr.delivery_warehouse_id in
#{item}
and wr.purchase_user_id in
#{item}
and wr.approve_status in
#{item}
and wr.create_user_id in
#{item}
and wr.bill_date >= #{params.billDate[0]} and (#{params.billDate[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > wr.bill_date
and wr.create_time >= #{params.createTime[0]} and (#{params.createTime[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > wr.create_time
${params.permissionSql }
ORDER BY
${item.field} ${item.sort}
wr.create_time desc

select count(distinct wr.id) FROM po_receive_detail wrd INNER JOIN po_receive wr ON wrd.main_id = wr.id AND wrd.is_deleted = FALSE WHERE wr.is_deleted = FALSE
and wr.approve_status in
#{item}
${params.permissionSql }

SELECT wr.approve_status, wrd.sku_id, wrd.sku_no, wr.purchase_order_id, SUM(wrd.receive_qty) AS receiveQty FROM po_receive_detail wrd INNER JOIN po_receive wr ON wrd.main_id = wr.id AND wrd.is_deleted = FALSE WHERE wr.is_deleted = FALSE and wr.invalid_status = FALSE
AND wr.purchase_order_id = #{purchaseOrderId}
GROUP BY wrd.sku_id, wrd.sku_no, wr.purchase_order_id, wr.approve_status

